<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionTemplateVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;

trait TemplateVersionTemplateAttributeHolder
{
    protected TemplateVersionTemplateVO|TemplateRef|null $template = null;
    protected bool $templateAssigned = false;

    public function getTemplateOrDefault(TemplateVersionTemplateVO $template): TemplateVersionTemplateVO
    {
        if ($this->templateAssigned) {
            \assert(null !== $this->template);
            return TemplateVersionTemplateVO::from($this->template);
        } else {
            return $template;
        }
    }
    public function template(TemplateVersionTemplateVO|TemplateRef $template): static
    {
        $this->template = $template;
        $this->templateAssigned = true;
        return $this;
    }
    public function getTemplate(): ?TemplateRef
    {
        return $this->template instanceof TemplateVersionTemplateVO ? $this->template->value() : $this->template;
    }
    public function isTemplateAssigned(): bool
    {
        return $this->templateAssigned;
    }
    public function writeTemplateTo(mixed $att): void
    {
        if ($this->templateAssigned) {
            \assert(null !== $this->template);
            $att->template($this->template);
        }
    }
    public function readTemplateFrom(mixed $att): void
    {
        if ($att->isTemplateAssigned()) {
            $template = $att->getTemplate();
            \assert(null !== $template);
            $this->template($template);
        }
    }
    public function unsetTemplate(): static
    {
        $this->templateAssigned = false;
        return $this;
    }
    protected function withDefaultTemplate(): void
    {
    }
    protected function withAssertedTemplateRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->templateAssigned = $this->templateAssigned) {
            $value->template = TemplateVersionTemplateVO::tryFrom($this->template, $errorsList);
        }
    }
}
